# Temperature reader for a Raspberry Pi using the DS18B20 over 1-Wire
# Reads a single temperature and prints it to standard output
import time
from w1thermsensor import W1ThermSensor, NoW1SensorsFoundError, SensorNotReadyError

def read_temperature():
    """Read and return the temperature from the DS18B20 sensor."""
    # Attempt to find the sensor on the 1-Wire bus
    try:
        sensor = W1ThermSensor()
    except NoW1SensorsFoundError:
        print("Error: No DS18B20 sensor found on the 1-Wire bus.")
        return None
    except Exception as sensor_error:
        print(f"Error initializing sensor: {sensor_error}")
        return None

    # Read the temperature from the sensor
    try:
        temperature_celsius = sensor.get_temperature()
    except SensorNotReadyError:
        print("Error: Sensor is not ready to read temperature.")
        return None
    except Exception as read_error:
        print(f"Error reading temperature: {read_error}")
        return None

    # Validate the temperature reading
    if not -55.0 <= temperature_celsius <= 125.0:
        print(f"Warning: Invalid temperature reading: {temperature_celsius}°C")
        return None

    return temperature_celsius

def main():
    """Main function to read and print the temperature."""
    try:
        # Read the temperature
        temperature = read_temperature()

        # Print the temperature if reading was successful
        if temperature is not None:
            print(f"Temperature: {temperature:.2f} °C")

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # No specific cleanup needed for w1thermsensor, but include a placeholder
        print("Exiting temperature reader.")

if __name__ == "__main__":
    main()

