def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_adc(i2c_bus):
    """Initializes the ADS1115 ADC."""
    try:
        return ADS.ADS1115(i2c_bus)
    except Exception as e:
        print(f"Error initializing ADC: {e}")
        return None

def initialize_analog_input(adc_device, channel=0):
    """Initializes an analog input on the specified channel."""
    try:
        return AnalogIn(adc_device, channel)
    except Exception as e:
        print(f"Error initializing analog input: {e}")
        return None

def read_adc_value(analog_input):
    """Reads the raw ADC value from the specified input."""
    try:
        return analog_input.value
    except Exception as e:
        print(f"Error reading ADC value: {e}")
        return None

def validate_adc_reading(reading):
    """Validates that the ADC reading is within the expected range."""
    if reading is None:
        return False
    return -32768 <= reading <= 32767

def print_adc_reading(reading, channel):
    """Prints the ADC reading to the console."""
    print(f"Channel {channel}: {reading}")

