    if analog_input is None:
        return 1  # Indicate failure

    try:
        for _ in range(NUMBER_OF_READINGS):
            adc_value = read_adc_value(analog_input)

            if validate_adc_reading(adc_value):
                print_adc_reading(adc_value, 0)  # Assuming channel 0

