    """Initialize the I2C bus and MCP3008 ADC."""
    i2c_bus = busio.I2C(board.SCL, board.SDA)
    return MCP.MCP3008(i2c_bus)

def read_channel(adc_device, channel_index):
    """Read a single channel from the ADC and return the value."""
    if not 0 <= channel_index < CHANNEL_COUNT:
        raise ValueError("Invalid channel index")
    return adc_device.value(channel_index)

def validate_reading(reading_value):
    """Validate that the reading is within the expected range."""
    return 0 <= reading_value <= 1023

def print_reading(channel_index, reading_value):
