    """Main function to read and display ADC values."""
    adc_device = None
    try:
        adc_device = initialize_adc()
        for sample_index in range(SAMPLE_COUNT):
            try:
                channel_value = read_channel(adc_device, 0)
                if validate_reading(channel_value):
                    print_reading(0, channel_value)
                else:
                    print(f"Invalid reading: {channel_value}")
            except Exception as read_error:
                print(f"Error reading channel: {read_error}")
            time.sleep(1)
    except Exception as init_error:
        print(f"Initialization error: {init_error}")
    finally:
        if adc_device:
