# Initialize DHT22 sensors
dht_sensors = []
for pin in SENSOR_PINS:
    try:
        dht_sensor = adafruit_dht.DHT22(pin, use_pulseio=False)
        dht_sensors.append(dht_sensor)
    except Exception as e:
        print(f"Error initializing DHT22 sensor on pin {pin}: {e}")
        dht_sensors.append(None)

# Function to read temperature and humidity from a sensor
def read_sensor_data(sensor):
    """Reads temperature and humidity from a DHT22 sensor."""
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        return temperature, humidity
    except RuntimeError as e:
        print(f"Sensor reading error: {e}")
        return None, None
    except Exception as e:
        print(f"Unexpected error reading sensor: {e}")
        return None, None

# Function to apply a state to the GPIO pin
def apply_state(pin, state):
    """Applies a state (HIGH or LOW) to a GPIO pin."""
    try:
        GPIO.output(pin, state)
        print(f"Pin {pin}: State Applied - {state}")
    except Exception as e:
        print(f"Error applying state to pin {pin}: {e}")

# Main function to orchestrate the state change
def main():
    """Main function to read sensor data and apply states."""
    try:
        for _ in range(3):
            for i, sensor in enumerate(dht_sensors):
                if sensor:
                    temperature, humidity = read_sensor_data(sensor)
                    if temperature is not None and humidity is not None:
                        print(f"Sensor {i+1} - Temperature: {temperature:.1f}C, Humidity: {humidity:.1f}%")
