# uart_communication_rpi.py
# Communicates with a device over UART on a Raspberry Pi

import serial
import time

# Define the serial port and baud rate
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_INTERVAL_SECONDS = 0.5

def initialize_serial(port, baud):
    """Initializes the serial connection."""
    try:
        ser = serial.Serial(port, baud, timeout=1)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def read_device_data(serial_connection):
    """Reads a line of data from the serial port."""
    try:
        data = serial_connection.readline().decode('ascii', errors='replace').strip()
        return data
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None

def display_data(data):
    """Prints the received data to the console."""
    if data:
        print(f'Received: {data}')

def main():
    """Main function to establish serial communication and read data."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE)

    if serial_connection is None:
        print("Failed to initialize serial communication. Exiting.")
        return

    try:
        while True:
            data = read_device_data(serial_connection)
            display_data(data)
            time.sleep(READ_INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")

    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

# adc_reader_rpi.py
# Reads analog values from an ADS1015 ADC on a Raspberry Pi

import time
import board
import busio
import adafruit_ads1x15.ads1015 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# Define the I2C address of the ADS1015
ADS1015_ADDRESS = 0x19

def initialize_adc():
    """Initializes the I2C bus and ADC."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        adc_device = ADS.ADS1015(i2c_bus, address=ADS1015_ADDRESS)
        return adc_device
    except Exception as e:
        print(f"Error initializing ADC: {e}")
        return None

def read_adc_channel(adc_device, channel_number):
    """Reads a single channel from the ADC."""
    try:
        if channel_number < 0 or channel_number > 3:
            raise ValueError("Invalid channel number. Must be between 0 and 3.")
        analog_input = AnalogIn(adc_device, channel_number)
        return analog_input.value
    except Exception as e:
        print(f"Error reading ADC channel {channel_number}: {e}")
        return None

def main():
    """Main function to read and print ADC values."""
    adc = initialize_adc()
    if adc is None:
        exit(1)

    try:
        while True:
            for channel in range(4):
                value = read_adc_channel(adc, channel)
                if value is not None:
                    print(f"Channel {channel}: {value}")
            time.sleep(1)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        # No specific cleanup needed for adafruit_ads1x15, but included for completeness
        print("Exiting program.")

if __name__ == "__main__":
    main()

# Analog channel reader for Raspberry Pi using MCP3008 ADC
# Reads a single channel and prints the value to the console
import time
import board
import busio
import adafruit_mcp3xxx.mcp3008 as MCP

# Configuration
CHANNEL_NUMBER = 0
SAMPLE_INTERVAL = 0.1

def initialize_adc():
    """Initialize the I2C bus and MCP3008 ADC."""
    i2c_bus = busio.I2C(board.SCL, board.SDA)
    return MCP.MCP3008(i2c_bus)

def read_channel(adc_device, channel):
    """Read a single channel from the ADC and return the value."""
    return adc_device.value(channel)

def is_valid_reading(reading):
    """Check if the reading is within the valid range."""
    return 0 <= reading <= 1023

def print_reading(reading):
    """Print the reading to the console."""
    print(f"Channel {CHANNEL_NUMBER}: {reading}")

def main():
    """Main function to read and display ADC values."""
    adc = initialize_adc()
    try:
        while True:
            raw_value = read_channel(adc, CHANNEL_NUMBER)
            if is_valid_reading(raw_value):
                print_reading(raw_value)
            time.sleep(SAMPLE_INTERVAL)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        adc.release()
        print("ADC resources released.")

if __name__ == "__main__":
    main()

