# gpiozero-ultrasonic-trigger-event-driven.py
# Event-driven ultrasonic distance measurement on Raspberry Pi using gpiozero

import time
from gpiozero import DistanceSensor

# Define GPIO pins for the ultrasonic sensors
TRIGGER_PINS = [5, 6, 17, 18, 22, 23, 24, 27]
ECHO_PINS = [6, 13, 19, 20, 21, 26, 25, 27]

# Initialize distance sensors
distance_sensors = []
for i in range(len(TRIGGER_PINS)):
    try:
        distance_sensors.append(DistanceSensor(echo=ECHO_PINS[i], trigger=TRIGGER_PINS[i]))
    except Exception as e:
        print(f"Error initializing sensor {i+1}: {e}")
        exit()

# Function to handle distance measurement
def measure_distance(sensor_index):
    """Measures the distance from the specified sensor and prints the result."""
    try:
        distance = distance_sensors[sensor_index].distance * 100  # Convert to cm
        print(f"Sensor {sensor_index + 1}: Distance = {distance:.2f} cm")
    except Exception as e:
        print(f"Error reading sensor {sensor_index + 1}: {e}")

# Main loop
try:
    while True:
        for i in range(len(distance_sensors)):
            measure_distance(i)
        time.sleep(1)
except KeyboardInterrupt:
    print("Program terminated by user.")
except Exception as e:
    print(f"An unexpected error occurred: {e}")
finally:
    # Clean up resources
    for sensor in distance_sensors:
        sensor.close()
    print("GPIO resources released.")

